-- =====================================================================================================================
-- Eagle Labs Exam Portal: core schema for PostgreSQL / Supabase
--
-- Everything lives in the PRIVATE schema "eagle", which is never added to the Data API's exposed schemas. The browser
-- never talks to the database: only the application server does (see 20261024100100_eagle_security.sql and docs/SUPABASE.md).
--
-- Design notes (deliberate, to keep behaviour identical to the SQLite version this replaces):
--   * ids are bigint identity columns ("generated BY DEFAULT"), so existing ids can be loaded unchanged;
--   * timestamps are bigint epoch MILLISECONDS (UTC), exactly as the application computes them;
--   * flags are smallint 0/1 with CHECK constraints (the JSON API has always returned 0/1);
--   * question options / answer keys / settings are JSON text validated by the application;
--   * e-mail addresses are stored lower-case (CHECK) and unique; student numbers are unique ignoring case.
-- This file is applied inside one transaction, by `supabase db push` or `npm run migrate`.
-- =====================================================================================================================

create schema if not exists eagle;

-- Records which migrations have run. Every migration file registers itself on its last line, so the Supabase CLI and
-- `npm run migrate` leave the same trace.
create table if not exists eagle.schema_migrations(
  version    text primary key,
  name       text not null,
  applied_at timestamptz not null default now()
);

-- ---------- accounts ----------
create table eagle.users(
  id                bigint generated by default as identity primary key,
  email             text   not null,
  name              text   not null,
  role              text   not null check (role in ('admin','teacher','student')),
  student_number    text,
  pw_hash           text   not null,
  status            text   not null default 'active' check (status in ('active','suspended')),
  must_change       smallint not null default 0 check (must_change in (0,1)),
  created           bigint not null,
  last_login        bigint,
  email_verified_at bigint,
  otp_exempt        smallint not null default 0 check (otp_exempt in (0,1)),
  constraint users_email_key unique (email),
  constraint users_email_is_lowercase check (email = lower(email)),
  -- only student accounts may sign in with a password alone (never staff)
  constraint users_otp_exempt_students_only check (otp_exempt = 0 or role = 'student')
);
create unique index users_student_number_key on eagle.users (lower(student_number)) where student_number is not null and student_number <> '';
create index idx_users_role_name on eagle.users (role, lower(name));

create table eagle.sessions(
  token_hash text primary key,                       -- SHA-256 of the cookie value; the cookie itself is never stored
  user_id    bigint not null references eagle.users(id) on delete cascade,
  created    bigint not null,
  expires    bigint not null
);
create index idx_sessions_user on eagle.sessions (user_id);
create index idx_sessions_expires on eagle.sessions (expires);

-- ---------- subjects, classes ----------
create table eagle.subjects(
  id   bigint generated by default as identity primary key,
  name text not null
);
create unique index subjects_name_key on eagle.subjects (lower(name));
insert into eagle.subjects(name) values ('Mathematics');

create table eagle.classes(
  id            bigint generated by default as identity primary key,
  name          text not null,
  grade         text,
  academic_year text,
  subject_id    bigint references eagle.subjects(id),
  created_by    bigint references eagle.users(id),
  created       bigint not null,
  archived      smallint not null default 0 check (archived in (0,1))
);
create index idx_classes_subject on eagle.classes (subject_id);
create index idx_classes_created_by on eagle.classes (created_by);

create table eagle.class_members(
  class_id bigint not null references eagle.classes(id) on delete cascade,
  user_id  bigint not null references eagle.users(id) on delete cascade,
  role     text   not null check (role in ('teacher','student')),
  primary key (class_id, user_id)
);
create index idx_members_user on eagle.class_members (user_id);

create table eagle.images(
  id       bigint generated by default as identity primary key,
  owner_id bigint not null references eagle.users(id),
  mime     text   not null,
  data     bytea  not null,
  created  bigint not null
);
create index idx_images_owner on eagle.images (owner_id);

-- ---------- reusable question bank ----------
create table eagle.questions(
  id          bigint generated by default as identity primary key,
  owner_id    bigint not null references eagle.users(id),
  subject_id  bigint references eagle.subjects(id),
  type        text   not null check (type in ('mcq','tf','short','numeric','written')),
  stem        text   not null,
  options     text   not null default '[]',
  key         text   not null default '{}',           -- the ANSWER KEY: only ever read by the server, never sent to students early
  settings    text   not null default '{}',
  marks       double precision not null default 1 check (marks >= 0),
  topic       text   not null default '',
  difficulty  text   not null default 'medium' check (difficulty in ('easy','medium','hard')),
  explanation text   not null default '',
  image_id    bigint references eagle.images(id),
  version     integer not null default 1,
  archived    smallint not null default 0 check (archived in (0,1)),
  created     bigint not null,
  updated     bigint not null
);
create index idx_questions_owner on eagle.questions (owner_id, archived, topic);
create index idx_questions_subject on eagle.questions (subject_id);
create index idx_questions_image on eagle.questions (image_id);

-- ---------- exams ----------
create table eagle.exams(
  id             bigint generated by default as identity primary key,
  owner_id       bigint not null references eagle.users(id),
  subject_id     bigint references eagle.subjects(id),
  title          text   not null,
  instructions   text   not null default '',
  minutes        integer not null default 30 check (minutes between 1 and 600),
  opens          bigint,
  closes         bigint,
  status         text   not null default 'draft' check (status in ('draft','published','closed','archived')),
  max_attempts   integer not null default 1 check (max_attempts between 1 and 5),
  shuffle_q      smallint not null default 0 check (shuffle_q in (0,1)),
  shuffle_o      smallint not null default 0 check (shuffle_o in (0,1)),
  release_mode   text   not null default 'manual' check (release_mode in ('manual','on_finalize','immediate')),
  show_answers   smallint not null default 0 check (show_answers in (0,1)),
  grace_s        integer not null default 15 check (grace_s between 0 and 300),
  declared_total double precision check (declared_total is null or declared_total > 0),
  version        integer not null default 1,
  created        bigint not null,
  updated        bigint not null,
  published_at   bigint,
  pass_mark      double precision check (pass_mark is null or pass_mark between 0 and 100),
  academic_year  text,
  term           text,
  grade          text,
  constraint exams_window_order check (opens is null or closes is null or closes > opens)
);
create index idx_exams_owner on eagle.exams (owner_id, status);
create index idx_exams_subject on eagle.exams (subject_id);
create index idx_exams_year on eagle.exams (academic_year, term);

create table eagle.exam_classes(
  exam_id  bigint not null references eagle.exams(id) on delete cascade,
  class_id bigint not null references eagle.classes(id),
  primary key (exam_id, class_id)
);
create index idx_exam_classes_class on eagle.exam_classes (class_id);

-- Direct (per-student) enrollment. Class assignment through exam_classes still works unchanged.
create table eagle.exam_students(
  exam_id     bigint not null references eagle.exams(id) on delete cascade,
  student_id  bigint not null references eagle.users(id),
  enrolled_by bigint references eagle.users(id),
  enrolled_at bigint not null,
  primary key (exam_id, student_id)
);
create index idx_exam_students_student on eagle.exam_students (student_id);
create index idx_exam_students_by on eagle.exam_students (enrolled_by);

-- Exam-specific SNAPSHOTS of question content: editing the bank never rewrites an exam that was already published.
create table eagle.exam_questions(
  id             bigint generated by default as identity primary key,
  exam_id        bigint not null references eagle.exams(id) on delete cascade,
  pos            integer not null,
  section        text   not null default '',
  source_qid     bigint references eagle.questions(id),
  source_version integer,
  type           text   not null check (type in ('mcq','tf','short','numeric','written')),
  stem           text   not null,
  options        text   not null default '[]',
  key            text   not null default '{}',          -- the ANSWER KEY snapshot
  settings       text   not null default '{}',
  marks          double precision not null default 1 check (marks >= 0),
  topic          text   not null default '',
  difficulty     text   not null default 'medium' check (difficulty in ('easy','medium','hard')),
  explanation    text   not null default '',
  image_id       bigint references eagle.images(id)
);
create index idx_eq_exam on eagle.exam_questions (exam_id, pos);
create index idx_eq_source on eagle.exam_questions (source_qid);
create index idx_eq_image on eagle.exam_questions (image_id);

create table eagle.accommodations(
  exam_id        bigint not null references eagle.exams(id) on delete cascade,
  student_id     bigint not null references eagle.users(id),
  extra_minutes  integer not null default 0 check (extra_minutes between 0 and 240),
  extra_attempts integer not null default 0 check (extra_attempts between 0 and 3),
  note           text   not null default '',
  primary key (exam_id, student_id)
);
create index idx_accommodations_student on eagle.accommodations (student_id);

-- ---------- attempts, answers, grades ----------
create table eagle.attempts(
  id             bigint generated by default as identity primary key,
  exam_id        bigint not null references eagle.exams(id),
  student_id     bigint not null references eagle.users(id),
  attempt_no     integer not null check (attempt_no >= 1),
  started        bigint not null,
  deadline       bigint not null,
  extra_s        integer not null default 0,
  status         text   not null default 'in_progress' check (status in ('in_progress','submitted','auto_submitted')),
  submitted_at   bigint,
  receipt        text,
  seed           integer not null,
  score          double precision,
  total          double precision,
  grading_status text check (grading_status in ('pending','graded')),
  finalized_at   bigint,
  finalized_by   bigint references eagle.users(id),
  released_at    bigint,
  constraint attempts_attempt_key unique (exam_id, student_id, attempt_no)
);
-- A student can have at most ONE running attempt per exam, whatever the browser sends (double-clicks, two tabs, retries).
create unique index one_active_attempt on eagle.attempts (exam_id, student_id) where status = 'in_progress';
create index idx_attempts_exam on eagle.attempts (exam_id, status);
create index idx_attempts_student on eagle.attempts (student_id);
create index idx_attempts_grading on eagle.attempts (exam_id, grading_status, status);
create index idx_attempts_finalized_by on eagle.attempts (finalized_by);
create index idx_attempts_open_deadline on eagle.attempts (deadline) where status = 'in_progress';

create table eagle.answers(
  attempt_id bigint not null references eagle.attempts(id) on delete cascade,
  eq_id      bigint not null references eagle.exam_questions(id),
  value      text,
  seq        integer not null default 0,
  flagged    smallint not null default 0 check (flagged in (0,1)),
  updated    bigint not null,
  primary key (attempt_id, eq_id)
);
create index idx_answers_eq on eagle.answers (eq_id);

create table eagle.grades(
  attempt_id bigint not null references eagle.attempts(id) on delete cascade,
  eq_id      bigint not null references eagle.exam_questions(id),
  marks      double precision not null default 0 check (marks >= 0),
  status     text   not null check (status in ('auto','pending','graded')),
  feedback   text   not null default '',
  graded_by  bigint references eagle.users(id),
  graded_at  bigint,
  primary key (attempt_id, eq_id)
);
create index idx_grades_eq on eagle.grades (eq_id);
create index idx_grades_graded_by on eagle.grades (graded_by);
create index idx_grades_pending on eagle.grades (attempt_id) where status = 'pending';

-- Every manual mark change, with who/when/why. Append-only (trigger below; the application role also has no UPDATE/DELETE).
create table eagle.grade_history(
  id         bigint generated by default as identity primary key,
  attempt_id bigint not null,
  eq_id      bigint not null,
  old_marks  double precision,
  new_marks  double precision not null,
  old_status text,
  by_user    bigint not null,
  at         bigint not null,
  reason     text   not null default ''
);
create index idx_grade_history_attempt on eagle.grade_history (attempt_id, eq_id);

create table eagle.attempt_events(
  id         bigint generated by default as identity primary key,
  attempt_id bigint not null references eagle.attempts(id) on delete cascade,
  ts         bigint not null,
  kind       text   not null
);
create index idx_events_attempt on eagle.attempt_events (attempt_id);

-- ---------- append-only audit trail ----------
create table eagle.audit(
  id          bigint generated by default as identity primary key,
  ts          bigint not null,
  actor_id    bigint,
  actor_email text,
  action      text   not null,
  resource    text,
  resource_id bigint,
  detail      text
);
create index idx_audit_ts on eagle.audit (ts);
create index idx_audit_actor on eagle.audit (actor_id);

-- ---------- school settings (exactly one row) ----------
create table eagle.school_settings(
  id                smallint primary key check (id = 1),
  school_name       text not null default 'Eagle Labs Exam Portal',
  timezone          text not null default 'Africa/Addis_Ababa',
  locale            text not null default 'en' check (locale in ('en','am')),
  calendar          text not null default 'gregory' check (calendar in ('gregory','ethiopic')),
  default_pass_mark double precision not null default 50 check (default_pass_mark between 0 and 100),
  grading_scale     text not null default '[]',
  terms             text not null default '["Semester 1","Semester 2"]',
  brand_color       text not null default '#0b1f4d',
  updated           bigint not null default 0
);
insert into eagle.school_settings(id) values (1);

-- ---------- e-mail one-time codes (OTP) ----------
-- One pending challenge per user and purpose. Codes are stored only as keyed hashes; see lib/otp.js.
create table eagle.otp_challenges(
  id                bigint generated by default as identity primary key,
  token_hash        text   not null unique,
  user_id           bigint not null references eagle.users(id) on delete cascade,
  purpose           text   not null check (purpose in ('login','password_reset','code_login')),
  email             text   not null,
  code_hash         text   not null,
  code_expires      bigint not null,
  challenge_expires bigint not null,
  attempts          integer not null default 0 check (attempts >= 0),
  total_attempts    integer not null default 0 check (total_attempts >= 0),
  resends           integer not null default 0 check (resends >= 0),
  last_sent         bigint not null,
  created           bigint not null
);
create unique index idx_otp_user_purpose on eagle.otp_challenges (user_id, purpose);
create index idx_otp_expiry on eagle.otp_challenges (challenge_expires);

-- Rate-limit counters that survive restarts and are shared by every server instance. ip_hash is a keyed hash, never a raw address.
create table eagle.otp_events(
  id      bigint generated by default as identity primary key,
  ts      bigint not null,
  kind    text   not null check (kind in ('send','attempt','fail','test')),
  user_id bigint references eagle.users(id) on delete cascade,
  ip_hash text
);
create index idx_otp_events_user on eagle.otp_events (user_id, kind, ts);
create index idx_otp_events_ip on eagle.otp_events (ip_hash, kind, ts);
create index idx_otp_events_ts on eagle.otp_events (ts);

-- ---------- integrity triggers ----------
create function eagle.forbid_change() returns trigger language plpgsql as $$
begin
  raise exception '% is append-only', tg_table_name using errcode = 'restrict_violation';
end $$;

create trigger audit_append_only before update or delete on eagle.audit
  for each row execute function eagle.forbid_change();
create trigger audit_no_truncate before truncate on eagle.audit
  for each statement execute function eagle.forbid_change();
create trigger grade_history_append_only before update or delete on eagle.grade_history
  for each row execute function eagle.forbid_change();
create trigger grade_history_no_truncate before truncate on eagle.grade_history
  for each statement execute function eagle.forbid_change();

-- Defence in depth: only STUDENT accounts can be enrolled in an exam, even if application code is bypassed.
create function eagle.require_student_enrollee() returns trigger language plpgsql as $$
begin
  if coalesce((select role from eagle.users where id = new.student_id), '') <> 'student' then
    raise exception 'only student accounts can be enrolled' using errcode = 'check_violation';
  end if;
  return new;
end $$;
create trigger exam_students_role before insert or update of student_id on eagle.exam_students
  for each row execute function eagle.require_student_enrollee();

insert into eagle.schema_migrations(version, name) values ('20261024100000', 'eagle_core_schema') on conflict do nothing;
